{
  "name": "@zachre/opencode-computer-use",
  "version": "0.1.0",
  "description": "OpenCode plugin that registers the Open Computer Use native CLI, its stdio MCP server, and the agent skill in one installable package.",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./src/server.js"
  },
  "files": [
    "src/",
    "skills/",
    "LICENSE",
    "THIRD_PARTY_NOTICES.md",
    "README.md"
  ],
  "scripts": {
    "test": "node test/plugin-setup.test.mjs && node test/runtime-layouts.test.mjs",
    "version:check": "node scripts/version.mjs check",
    "version:set": "node scripts/version.mjs set",
    "pack:release": "node scripts/pack.mjs",
    "verify:release": "node scripts/pack.mjs --verify",
    "release:gate": "npm test && npm run version:check && npm run pack:release && npm run verify:release",
    "scan:defender": "powershell -NoProfile -ExecutionPolicy Bypass -File scripts/defender-scan.ps1"
  },
  "optionalDependencies": {
    "@zachre/opencode-computer-use-darwin": "0.1.0",
    "@zachre/opencode-computer-use-linux-arm64": "0.1.0",
    "@zachre/opencode-computer-use-linux-x64": "0.1.0",
    "@zachre/opencode-computer-use-win32-arm64": "0.1.0",
    "@zachre/opencode-computer-use-win32-x64": "0.1.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "computer-use",
    "mcp"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.3.2"
  },
  "publishConfig": {
    "access": "public"
  }
}

import { chmodSync, existsSync, readFileSync } from "node:fs"
import { readFile } from "node:fs/promises"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

import { Plugin } from "@opencode/plugin"

import { RUNTIMES, hostPlatformKey, resolveRuntimePath } from "./runtime.js"

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const PLUGIN_VERSION = JSON.parse(readFileSync(join(packageRoot, "package.json"), "utf8")).version

const SERVER_NAME = "open-computer-use"
const SKILL_ID = "open-computer-use"

function log(message) {
  console.log(`[computer-use] ${message}`)
}

function unwrapList(result) {
  const list = Array.isArray(result) ? result : (result?.data ?? [])
  return Array.isArray(list) ? list : []
}

function resolveExecutable(options) {
  const override = typeof options?.executable === "string" ? options.executable : undefined
  const platformKey = hostPlatformKey()
  const candidate = override ? resolve(override) : resolveRuntimePath(packageRoot, platformKey)

  if (!candidate || !existsSync(candidate)) {
    return undefined
  }
  if (process.platform !== "win32") {
    try {
      chmodSync(candidate, 0o755)
    } catch {
      // Best effort: a read-only install tree can still be executable already.
    }
  }
  return candidate
}

function splitFrontmatter(text) {
  if (!text.startsWith("---")) return { fields: {}, body: text.trim() }

  const end = text.indexOf("\n---", 3)
  if (end === -1) return { fields: {}, body: text.trim() }

  const header = text.slice(3, end)
  const fields = {}
  for (const line of header.split("\n")) {
    const match = line.match(/^([A-Za-z0-9_.-]+):\s*(.*)$/)
    if (!match) continue
    let value = match[2].trim()
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1)
    }
    fields[match[1]] = value
  }
  return { fields, body: text.slice(end + 4).trim() }
}

async function loadSkill() {
  const file = join(packageRoot, "skills", SKILL_ID, "SKILL.md")
  if (!existsSync(file)) return undefined

  const raw = await readFile(file, "utf8")
  const { fields, body } = splitFrontmatter(raw)

  return {
    id: SKILL_ID,
    name: fields.name || "Open Computer Use",
    description:
      fields.description ||
      "Use Open Computer Use to inspect and operate desktop applications through its native CLI or stdio MCP server.",
    autoinvoke: fields["disable-model-invocation"] === "true" ? false : true,
    // Skill-relative paths resolve from this directory, so references/ stay usable.
    path: file,
    content: body,
  }
}

export default Plugin.define({
  id: "computer-use",

  async setup(ctx) {
    const executable = resolveExecutable(ctx.options)
    const runtime = RUNTIMES[hostPlatformKey()]

    if (!executable) {
      const hint = runtime
        ? `Install the matching "${runtime.pkg}" package`
        : "Install a matching platform runtime package"
      console.error(
        `[computer-use] no runtime for ${hostPlatformKey()}. ${hint}, ` +
          `or set the plugin "executable" option to an Open Computer Use binary.`,
      )
      return
    }

    log(`runtime ${RUNTIMES[hostPlatformKey()]?.pkg ?? "external"} -> ${executable}`)

    await ctx.mcp.transform((editor) => {
      editor.set(SERVER_NAME, {
        type: "local",
        command: [executable, "mcp"],
        codemode: ctx.options?.codemode !== false,
      })
    })
    log(`registered MCP server "${SERVER_NAME}"`)

    if (ctx.options?.skill !== false) {
      const skill = await loadSkill()
      if (skill) {
        await ctx.skill.transform((editor) => {
          editor.add(skill)
        })
        log(`registered skill "${SKILL_ID}"`)
      } else {
        console.error(`[computer-use] skill payload missing at skills/${SKILL_ID}/SKILL.md`)
      }
    }

    await ctx.tool.transform((editor) => {
      editor.namespace({
        name: "computer-use",
        description: "Inspect the bundled Open Computer Use runtime, its MCP connection, and its skill.",
      })
      editor.add({
        name: "status",
        description:
          "Report which Open Computer Use runtime this plugin resolved, whether its MCP server is connected, and whether the skill is registered. Use it to diagnose a broken Computer Use setup before calling the native tools.",
        input: { type: "object", properties: {}, additionalProperties: false },
        options: { namespace: "computer-use", codemode: true },
        execute: async () => {
          const servers = unwrapList(await ctx.mcp.list())
          const skills = unwrapList(await ctx.skill.list())
          const server = servers.find((entry) => entry?.name === SERVER_NAME)
          const skill = skills.find((entry) => entry?.id === SKILL_ID)

          return {
            content: JSON.stringify(
              {
                pluginVersion: PLUGIN_VERSION,
                platform: hostPlatformKey(),
                runtimePackage: RUNTIMES[hostPlatformKey()]?.pkg,
                runtime: executable,
                mcp: {
                  name: SERVER_NAME,
                  status: server?.status?.status ?? "missing",
                  error: server?.status?.error,
                },
                skill: {
                  id: SKILL_ID,
                  registered: Boolean(skill),
                  path: skill?.path,
                },
              },
              null,
              2,
            ),
          }
        },
      })
    })
    log("registered status tool")
  },
})
